brute_force_code:
def remove_duplicates(arr):
    if not arr:
        return 0
    unique = []
    for x in arr:
        if not unique or unique[-1] != x:
            unique.append(x)
    for i, x in enumerate(unique):
        arr[i] = x
    return len(unique)

reference_solution:
def remove_duplicates(arr):
    if not arr:
        return 0
    slow = 0
    for fast in range(1, len(arr)):
        if arr[fast] != arr[slow]:
            slow += 1
            arr[slow] = arr[fast]
    return slow + 1
